54	// ── Plan Helpers ────────────────────────────────────────────
55	
56	/** Any paid plan (starter and above) */
57	export function isPaidPlan(plan: PlanType): boolean {
58	  return plan !== "free";
59	}
60	
61	/** Growth plan and above (growth, pro, agency) */
62	export function isGrowthPlus(plan: PlanType): boolean {
63	  return plan === "growth" || plan === "pro" || plan === "agency";
64	}
65	
66	/** Pro plan and above (pro, agency) */
67	export function isProPlus(plan: PlanType): boolean {
68	  return plan === "pro" || plan === "agency";
69	}
70	
71	/** Agency plan only */
72	export function isAgencyPlan(plan: PlanType): boolean {
73	  return plan === "agency";
74	}
