168	export function getPercentileLabel(score: number, benchmark: number): { label: string; color: string } {
169	  const diff = score - benchmark;
170	  if (diff >= 15) return { label: "Top 10%", color: "text-green-600" };
171	  if (diff >= 8) return { label: "Top 25%", color: "text-green-600" };
172	  if (diff >= 0) return { label: "Above Average", color: "text-emerald-600" };
173	  if (diff >= -8) return { label: "Below Average", color: "text-amber-600" };
174	  if (diff >= -15) return { label: "Bottom 25%", color: "text-red-500" };
175	  return { label: "Bottom 10%", color: "text-red-600" };
176	}
