179	
180	export function getTimeGreeting(): string {
181	  const hour = new Date().getHours();
182	  if (hour < 12) return "Good morning";
183	  if (hour < 17) return "Good afternoon";
184	  return "Good evening";
185	}
186	
187	export function formatRelativeDate(dateStr: string): string {
188	  const now = new Date();
189	  const date = new Date(dateStr);
190	  const diffMs = now.getTime() - date.getTime();
191	  const diffMins = Math.floor(diffMs / 60000);
192	  const diffHours = Math.floor(diffMs / 3600000);
193	  const diffDays = Math.floor(diffMs / 86400000);
194	
195	  if (diffMins < 1) return "Just now";
196	  if (diffMins < 60) return `${diffMins}m ago`;
197	  if (diffHours < 24) return `${diffHours}h ago`;
198	  if (diffDays < 7) return `${diffDays}d ago`;
199	  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
200	}
