809	export function generateAuditPDF(
810	  scan: Scan,
811	  pillarResults: PillarResult[],
812	  profile: { full_name: string; company_name?: string },
813	): void {
814	  const doc = new jsPDF({ unit: "mm", format: "a4", orientation: "portrait" });
815	
816	  const scanDate = scan.completed_at ?? scan.created_at;
817	  const dateStr = new Date(scanDate).toLocaleDateString("en-US", {
818	    month: "long",
819	    day: "numeric",
820	    year: "numeric",
821	  });
822	
823	  // Calculate total pages (cover + executive + pillar pages + quick wins)
824	  // We stamp footers after generation since jsPDF doesn't know page count upfront.
825	  // Instead we inject footers per-page after building all content.
826	
827	  // ── Build pages ─────────────────────────────────────────────────
828	  buildCoverPage(doc, scan, profile, dateStr);
829	  buildExecutiveSummary(doc, scan, pillarResults, dateStr);
830	  buildPillarPages(doc, pillarResults);
831	  buildQuickWinsPage(doc, pillarResults);
832	
833	  // ── Add footers to all pages ─────────────────────────────────────
834	  const totalPages = doc.getNumberOfPages();
835	  for (let p = 1; p <= totalPages; p++) {
836	    doc.setPage(p);
837	    addFooter(doc, p, totalPages, dateStr);
