840	  // ── Save ─────────────────────────────────────────────────────────
841	  const safeDomain = scan.url
842	    .replace(/^https?:\/\//, "")
843	    .replace(/[^a-zA-Z0-9-]/g, "-")
844	    .slice(0, 40);
845	  const filename = `ConvertScan-Audit-${safeDomain}-${new Date(scanDate).toISOString().slice(0, 10)}.pdf`;
846	  doc.save(filename);
847	}
