862	/** Hex "#RRGGBB" → [R, G, B] tuple. Falls back to BRAND.indigo on invalid input. */
863	function hexToRgb(hex: string): [number, number, number] {
864	  const cleaned = hex.replace("#", "");
865	  if (cleaned.length !== 6) return BRAND.indigo;
866	  const r = parseInt(cleaned.slice(0, 2), 16);
867	  const g = parseInt(cleaned.slice(2, 4), 16);
868	  const b = parseInt(cleaned.slice(4, 6), 16);
869	  if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return BRAND.indigo;
870	  return [r, g, b];
871	}
