import type { NextConfig } from 'next'
import { withSentryConfig } from '@sentry/nextjs'

const isDev = process.env.NODE_ENV !== 'production'

const securityHeaders = [
  {
    key: 'Strict-Transport-Security',
    value: 'max-age=63072000; includeSubDomains; preload',
  },
  {
    key: 'X-Frame-Options',
    value: 'DENY',
  },
  {
    key: 'X-Content-Type-Options',
    value: 'nosniff',
  },
  {
    key: 'Referrer-Policy',
    value: 'origin-when-cross-origin',
  },
  {
    key: 'Permissions-Policy',
    value: 'camera=(), microphone=(), geolocation=()',
  },
  {
    key: 'X-DNS-Prefetch-Control',
    value: 'on',
  },
  {
    key: 'Content-Security-Policy',
    value: [
      "default-src 'self'",
      `script-src 'self' 'unsafe-inline' ${isDev ? "'unsafe-eval'" : ''} https://app.posthog.com https://cdn.sentry.io`,
      "style-src 'self' 'unsafe-inline'",
      `img-src 'self' data: blob: https://*.supabase.co ${isDev ? 'http://127.0.0.1:54421' : ''}`,
      "font-src 'self' https://fonts.gstatic.com",
      `connect-src 'self' https://*.supabase.co https://app.posthog.com https://api.dodopayments.com https://*.sentry.io wss://*.supabase.co ${isDev ? 'http://127.0.0.1:54421 ws://127.0.0.1:54421 ws://localhost:3000 http://localhost:3000' : ''}`,
      "frame-ancestors 'none'",
      "worker-src 'self' blob:",
    ].join('; '),
  },
]

const nextConfig: NextConfig = {
  output: 'standalone',
  reactStrictMode: true,
  experimental: {},
  images: {
    remotePatterns: [
      {
        protocol: 'https',
        hostname: '*.supabase.co',
      },
    ],
  },
  async headers() {
    return [
      {
        source: '/:path*',
        headers: securityHeaders,
      },
    ]
  },
  typescript: {
    ignoreBuildErrors: false,
  },
}

export default process.env.NEXT_PUBLIC_SENTRY_DSN
  ? withSentryConfig(nextConfig, {
      org: process.env.SENTRY_ORG ?? 'boldteq',
      project: process.env.SENTRY_PROJECT ?? 'convertscan',
      silent: true,
      widenClientFileUpload: true,
      disableLogger: true,
    })
  : nextConfig

const config = {
  plugins: {
    '@tailwindcss/postcss': {},
  },
}

export default config

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* ──────────────────────────────────────────────────────────
     BRAND COLORS
  ────────────────────────────────────────────────────────── */
  --color-brand-indigo: #5B5FC7;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC PALETTE — LIGHT MODE
  ────────────────────────────────────────────────────────── */
  --color-background: oklch(99% 0 0);
  --color-foreground: oklch(18% 0.013 220);

  --color-card: oklch(100% 0 0);
  --color-card-foreground: oklch(18% 0.013 220);

  --color-popover: oklch(100% 0 0);
  --color-popover-foreground: oklch(18% 0.013 220);

  --color-primary: oklch(52% 0.19 264);
  --color-primary-foreground: oklch(100% 0 0);

  --color-secondary: oklch(96% 0.01 220);
  --color-secondary-foreground: oklch(18% 0.013 220);

  --color-muted: oklch(96% 0.01 220);
  --color-muted-foreground: oklch(46% 0.009 220);

  --color-accent: oklch(96% 0.01 220);
  --color-accent-foreground: oklch(18% 0.013 220);

  --color-destructive: oklch(51% 0.22 27);
  --color-destructive-foreground: oklch(100% 0 0);

  --color-success: oklch(56% 0.19 145);
  --color-success-foreground: oklch(100% 0 0);

  --color-warning: oklch(65% 0.18 72);
  --color-warning-foreground: oklch(100% 0 0);

  --color-border: oklch(93% 0.013 220);
  --color-input: oklch(93% 0.013 220);
  --color-ring: oklch(52% 0.19 264);

  --radius: 0.75rem;

  /* ──────────────────────────────────────────────────────────
