// ── Weighted Scoring ─────────────────────────────────────────

/** Pillar weights vary by page type — CTA matters more on landing pages */
const PAGE_TYPE_WEIGHTS: Record<PageType, Record<CroPillar, number>> = {
  landing: {
    value_proposition: 0.20, cta_effectiveness: 0.22, trust_signals: 0.18,
    visual_hierarchy: 0.10, mobile_experience: 0.12, content_copy: 0.10, page_performance: 0.08,
  },
  product: {
    value_proposition: 0.12, cta_effectiveness: 0.18, trust_signals: 0.22,
    visual_hierarchy: 0.10, mobile_experience: 0.15, content_copy: 0.13, page_performance: 0.10,
  },
  homepage: {
    value_proposition: 0.22, cta_effectiveness: 0.15, trust_signals: 0.15,
    visual_hierarchy: 0.15, mobile_experience: 0.12, content_copy: 0.12, page_performance: 0.09,
  },
  pricing: {
    value_proposition: 0.15, cta_effectiveness: 0.20, trust_signals: 0.22,
    visual_hierarchy: 0.12, mobile_experience: 0.10, content_copy: 0.13, page_performance: 0.08,
  },
  signup: {
    value_proposition: 0.18, cta_effectiveness: 0.25, trust_signals: 0.20,
    visual_hierarchy: 0.08, mobile_experience: 0.15, content_copy: 0.08, page_performance: 0.06,
  },
  blog: {
    value_proposition: 0.10, cta_effectiveness: 0.12, trust_signals: 0.08,
    visual_hierarchy: 0.15, mobile_experience: 0.15, content_copy: 0.25, page_performance: 0.15,
  },
  other: {
    value_proposition: 0.15, cta_effectiveness: 0.15, trust_signals: 0.15,
    visual_hierarchy: 0.14, mobile_experience: 0.14, content_copy: 0.14, page_performance: 0.13,
  },
}

export function getPillarWeight(pillar: CroPillar, pageType: PageType): number {
  return PAGE_TYPE_WEIGHTS[pageType]?.[pillar] ?? 0.14
}

export function calculateWeightedScore(results: PillarResult[], pageType: PageType): number {
  let totalWeight = 0
  let weightedSum = 0
  for (const r of results) {
    const w = getPillarWeight(r.pillar, pageType)
    weightedSum += r.score * w
    totalWeight += w
  }
  return totalWeight > 0 ? Math.round(weightedSum / totalWeight) : 0
}

