const INDUSTRY_BENCHMARKS: Record<CroPillar, number> = {
  value_proposition: 62,
  cta_effectiveness: 55,
  trust_signals: 48,
  visual_hierarchy: 67,
  mobile_experience: 58,
  content_copy: 60,
  page_performance: 72,
}

export function getIndustryBenchmark(pillar: CroPillar): number {
  return INDUSTRY_BENCHMARKS[pillar]
}

/** Returns percentile rank (0-100) — how this score compares to all scans */
export function getPercentileRank(score: number): number {
  if (score >= 90) return 97
  if (score >= 80) return 88
  if (score >= 70) return 72
  if (score >= 60) return 55
  if (score >= 50) return 38
  if (score >= 40) return 22
  if (score >= 30) return 12
  return 5
}

export function formatScore(score: number): string {
  return Math.round(score).toString()
}

export function getPercentileLabel(score: number, benchmark: number): { label: string; color: string } {
  const diff = score - benchmark
  if (diff >= 15) return { label: 'Top 10%', color: 'text-green-600' }
  if (diff >= 8) return { label: 'Top 25%', color: 'text-green-600' }
  if (diff >= 0) return { label: 'Above Average', color: 'text-emerald-600' }
  if (diff >= -8) return { label: 'Below Average', color: 'text-amber-600' }
  if (diff >= -15) return { label: 'Bottom 25%', color: 'text-red-500' }
  return { label: 'Bottom 10%', color: 'text-red-600' }
}

// ── Time Helpers ─────────────────────────────────────────────

export function getTimeGreeting(): string {
  const hour = new Date().getHours()
  if (hour < 12) return 'Good morning'
  if (hour < 17) return 'Good afternoon'
  return 'Good evening'
}

export function formatRelativeDate(dateStr: string): string {
  const now = new Date()
  const date = new Date(dateStr)
  const diffMs = now.getTime() - date.getTime()
  const diffMins = Math.floor(diffMs / 60000)
  const diffHours = Math.floor(diffMs / 3600000)
  const diffDays = Math.floor(diffMs / 86400000)

  if (diffMins < 1) return 'Just now'
  if (diffMins < 60) return `${diffMins}m ago`
  if (diffHours < 24) return `${diffHours}h ago`
  if (diffDays < 7) return `${diffDays}d ago`
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
}

import { redirect } from 'next/navigation'

export default function Home() {
  redirect('/login')
}

